    assert r.stdout == b'\\section{Heading\n\\emph{one}}\n\n\\subsection{Setext\nheading}\n\nA\nparagraph\nwith\n\\emph{emph},\n\\textbf{strong},\n\\emph{\\textbf{both}},\n\\texttt{code},\na\n\\href{http://example.com}{link},\nan\n\\protect\\includegraphics{img.png},\n\\url{http://auto.link},\n\\href{mailto:me@example.com}{\\nolinkurl{me@example.com}},\na\nhard\\\\\nbreak\nand\na\nsoft\nbreak.\nEntities:\n\xc2\xa9\n\\textquotesingle{}\n\\textquotesingle{}\n~.\nBackslash\n*\nescapes.\n\n\\begin{quote}\nA\nblock\nquote\nwith\n\\emph{two}\nlines\n\n\\begin{quote}\nnested\nquote\n\n\\end{quote}\n\n\\end{quote}\n\n\\begin{enumerate}\n\\item first\n\n\\item second\n\n\\begin{itemize}\n\\item nested\nbullet\n\n\\item another\n\nwith\na\nparagraph\n\n\\end{itemize}\n\n\\item third\n\n\\end{enumerate}\n\n\\begin{itemize}\n\\item {[}\n{]}\nnot\na\ntask\nlist\n\n\\end{itemize}\n\n\\begin{itemize}\n\\item different\nbullet\n\n\\end{itemize}\n\n\\begin{verbatim}\ndef f(x):\n    return x * 2\n\\end{verbatim}\n\n\\begin{verbatim}\nindented code block\n\\end{verbatim}\n\nInline\nhtml\nand\n.\n\n\\begin{center}\\rule{0.5\\linewidth}{\\linethickness}\\end{center}\n\n{ref\nlink}\nand\n{collapsed}\nand\n\\href{http://x.y}{shortcut}.\n'
    assert r.stderr == b''
    assert r.returncode == 0


