    assert r.stdout == b'.IP \\[bu] 2\na\n.IP \\[bu] 2\nb\n.IP \\[bu] 2\nc\n.IP "1." 4\nx\n.IP "2." 4\ny\n.IP "10." 4\nten\n.IP "11." 4\neleven\n.IP \\[bu] 2\nloose\n.RS\n.PP\npara\n.RE\n.IP \\[bu] 2\ntight\n'
    assert r.stderr == b''
    assert r.returncode == 0


