def test_quotes_and_dashes_man_width_0(run):
    r = run(args=['-t', 'man', '--width', '0'], stdin=b'"Hello," said the spider. \'Shelob\' is my name -- or --- maybe... it\'s 1990\'s.\n')
    assert r.stdout == b'.PP\n"Hello," said the spider. \'Shelob\' is my name \\-\\- or \\-\\-\\- maybe... it\'s 1990\'s.\n'
    assert r.stderr == b''
    assert r.returncode == 0


