    assert r.stdout == b'\\textquotedbl{}Hello,\\textquotedbl{}\nsaid the spider.\n\\textquotesingle{}Shelob\\textquotesingle{}\nis my name -{}- or\n-{}-{}- maybe...\nit\\textquotesingle{}s 1990\\textquotesingle{}s.\n'
    assert r.stderr == b''
    assert r.returncode == 0


