    assert r.stdout == b'.PP\na (b c) d (e(f)g) h (i)j) k (l) n (javascript:alert(1))\no (data:image/png;base64,x) p (vbscript:x) q (file:///etc) [IMAGE: r]\njavascript:y (javascript:y)\n'
    assert r.stderr == b''
    assert r.returncode == 0


