def test_raw_html_man_width_0(run):
    r = run(args=['-t', 'man', '--width', '0'], stdin=b'<script>alert(1)</script>\n\n<p onclick="x">p</p>\n\nInline <b onmouseover=x>b</b> <?php ?> <!DOCTYPE x> <![CDATA[ y ]]>\n')
    assert r.stdout == b'.PP\nInline b   \n'
    assert r.stderr == b''
    assert r.returncode == 0


