def test_headings_man_width_0(run):
    r = run(args=['-t', 'man', '--width', '0'], stdin=b'# h1\n## h2 ##\n### h3 #\n#### h4\n##### h5\n###### h6\n####### not\n\nH\n=\n\nH2\n---\n')
    assert r.stdout == b'.SH\nh1\n.SS\nh2\n.SS\nh3\n.SS\nh4\n.SS\nh5\n.SS\nh6\n.PP\n####### not\n.SH\nH\n.SS\nH2\n'
    assert r.stderr == b''
    assert r.returncode == 0


