def test_code_man_width_0(run):
    r = run(args=['-t', 'man', '--width', '0'], stdin=b'``` js {.class}\nconsole.log(`x`);\n```\n\n~~~~\n~~~\n~~~~\n\n`` a`b ``\n\n````\n```\n````\n')
    assert r.stdout == b'.IP\n.nf\n\\f[C]\nconsole.log(`x`);\n\\f[]\n.fi\n.IP\n.nf\n\\f[C]\n~~~\n\\f[]\n.fi\n.PP\n\\f[C]a`b\\f[]\n.IP\n.nf\n\\f[C]\n```\n\\f[]\n.fi\n'
    assert r.stderr == b''
    assert r.returncode == 0


