    assert r.stdout == b'.PP\n\xc3\x9cn\xc3\xafc\xc3\xb6d\xc3\xa9\n\\[em]\n\\[lq]quotes\\[rq]\n\\[oq]single\\[cq]\n\xe6\x97\xa5\xe6\x9c\xac\xe8\xaa\x9e\n\\f[I]\xe5\xbc\xb7\xe8\xaa\xbf\\f[]\n\xf0\x9f\x98\x80 \xc2\xa0nbsp\n'
    assert r.stderr == b''
    assert r.returncode == 0


